(()=>{'use strict';const teachers=[{name:'محسن اکبری',key:'mohsen-akbari',position:'50% 34%'},{name:'اکبری',key:'akbari',position:'50% 25%',manager:true},{name:'جعفری',key:'jafari',position:'57% 26%'},{name:'علیرضایی',key:'alirezaei',position:'50% 30%'},{name:'کرمی',key:'karami',position:'50% 35%'},{name:'فروغی',key:'foroughi',position:'40% 32%'},{name:'رضایی',key:'rezaei',position:'50% 30%'}];const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function find(name){let n=String(name||'').replace(/فروقی/g,'فروغی').replace(/^استاد\s+/,'').trim();return teachers.find(t=>n===t.name||n.startsWith(t.name+' ('))}function image(t,cls){return `<img class="${cls}" src="teachers/${t.key}.webp" alt="استاد ${t.name}" loading="lazy" style="object-position:${t.position}">`}
window.teacherInline=name=>{const t=find(name),n=String(name||'').replace(/فروقی/g,'فروغی').replace(/^استاد\s+/,'');return `<span class="teacher-person">${t?image(t,'teacher-avatar'):''}<span>استاد ${escape(n)}</span></span>`};
function decorate(root){root.querySelectorAll('.master,.teachergrid .card').forEach(card=>{const h=card.querySelector('h3');if(!h)return;const t=find(h.textContent);if(!t)return;h.textContent='استاد '+t.name;if(card.querySelector('.teacher-card-photo'))return;const old=card.querySelector('.glass,.avatar');const el=document.createElement('div');el.className='teacher-card-photo';el.innerHTML=image(t,'teacher-photo');if(old)old.replaceWith(el);else card.prepend(el);if(t.manager){const badge=document.createElement('span');badge.className='teacher-manager-badge';badge.textContent='مدیر آموزشگاه · مدرس';h.after(badge)}});
const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){if(!node.nodeValue.includes('استاد '))return NodeFilter.FILTER_REJECT;const p=node.parentElement;if(!p||p.closest('script,style,button,textarea,input,option,select,.teacher-person,.master,.teachergrid,h1,h2,h3,h4'))return NodeFilter.FILTER_REJECT;return NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);const pattern=/استاد\s+(محسن اکبری|علیرضایی|جعفری|فروغی|فروقی|رضایی|کرمی|اکبری)(?=\s|[·،؛().]|$)/g;for(const node of nodes){const value=node.nodeValue;let end=0,found=false,fragment=document.createDocumentFragment();for(const match of value.matchAll(pattern)){found=true;fragment.append(document.createTextNode(value.slice(end,match.index)));const holder=document.createElement('span');holder.innerHTML=window.teacherInline(match[1]);fragment.append(...holder.childNodes);end=match.index+match[0].length}if(found){fragment.append(document.createTextNode(value.slice(end)));node.replaceWith(fragment)}}}
function run(){observer.disconnect();decorate(document.body);observer.observe(document.body,{childList:true,subtree:true})}let queued=false;const observer=new MutationObserver(()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;run()})});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();})();
